WITH parsed AS (SELECT id, created_at, coupon_codes, attributes, SIZE(attributes) AS num_attributes, attributes['device'] AS device, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, SIZE(items) AS num_items FROM carts) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, DATE_TRUNC('HOUR', created_at) AS hour_window, CASE WHEN num_items >= 3 THEN 'LARGE' ELSE 'SMALL' END AS num_items_tier, MAX(num_attributes) AS max_num_attributes, COUNT(DISTINCT device) AS distinct_devices, ROUND(AVG(num_items), 2) AS avg_num_items FROM parsed GROUP BY 1, 2, 3;
